import{_ as n,c as t,o as i,ag as o}from"./chunks/framework.B3RpK1bM.js";const u=JSON.parse('{"title":"Explanation of Principles","description":"","frontmatter":{},"headers":[],"relativePath":"en_EN/explanation-principle-description.md","filePath":"en_EN/explanation-principle-description.md","lastUpdated":1769658044000}'),a={name:"en_EN/explanation-principle-description.md"};function r(s,e,c,l,d,p){return i(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="explanation-of-principles" tabindex="-1">Explanation of Principles <a class="header-anchor" href="#explanation-of-principles" aria-label="Permalink to &quot;Explanation of Principles&quot;">​</a></h1><p><a href="./">Return to Table of Contents</a></p><p><strong>Deep Development</strong> uses the make toolchain to convert script files into <code>./ezgal/csharp/FlowData.cs</code>, while <strong>Low Code Development</strong> relies on <code>./ezgal/csharp/Global.cs</code> to read script files within <code>./ezgal/script</code> at runtime. Script scenes in these files are then called uniformly from <code>./ezgal/scene/game.tscn</code>.</p><h2 id="parsing-to-json" tabindex="-1">Parsing to JSON <a class="header-anchor" href="#parsing-to-json" aria-label="Permalink to &quot;Parsing to JSON&quot;">​</a></h2><p>The parsing process in <code>./ezgal/csharp/Global.cs</code> is consistent with the implementation of the make toolchain, and its core parsing tools are the <code>read_file()</code> function. The core implementation functions include:</p><h3 id="line-by-line-processing" tabindex="-1">Line-by-Line Processing <a class="header-anchor" href="#line-by-line-processing" aria-label="Permalink to &quot;Line-by-Line Processing&quot;">​</a></h3><p>Reads through the file, processing each line sequentially until it reaches the end of the current line (<code>string line</code>). Only lines that are not null after trimming their head and tail whitespace characters are considered valid.</p><h3 id="handling-brackets" tabindex="-1">Handling Brackets <a class="header-anchor" href="#handling-brackets" aria-label="Permalink to &quot;Handling Brackets&quot;">​</a></h3><p>When encountering an opening bracket <code>{</code> (left brace), the current line continues adding information until it encounters a closing bracket <code>}</code> (right brace). Information within curly braces is handled by the <code>set_braces_func1()</code> function.</p><h3 id="option-handling" tabindex="-1">Option Handling <a class="header-anchor" href="#option-handling" aria-label="Permalink to &quot;Option Handling&quot;">​</a></h3><p>When reading <code>[options]</code>, the type is set as <code>&quot;options&quot;</code>. Subsequent lines are stored as options using the <code>set_option</code> function before continuing.</p><h2 id="logical-processing-for-json-format" tabindex="-1">Logical Processing for JSON Format <a class="header-anchor" href="#logical-processing-for-json-format" aria-label="Permalink to &quot;Logical Processing for JSON Format&quot;">​</a></h2><h3 id="text-processing" tabindex="-1">Text Processing <a class="header-anchor" href="#text-processing" aria-label="Permalink to &quot;Text Processing&quot;">​</a></h3><p>Text processing requires setting either <code>type=&quot;dialogue&quot;</code> or <code>type=&quot;full screen&quot;</code>. Based on this type, text will be displayed in the corresponding window. When <code>type</code> becomes empty, it automatically resumes the last stored <code>type</code> value.</p><ul><li>Image Function Set: You can add image functionality during text processing, which updates in the current row.</li><li>Sound Function Set: Similarly, you can add sound functionality during text processing, which also updates in the current row.</li><li>Navigation Function Set: You can add navigation functionality during text processing, which jumps to the next scene after completing the text processing.</li></ul><h3 id="independent-scene-execution" tabindex="-1">Independent Scene Execution <a class="header-anchor" href="#independent-scene-execution" aria-label="Permalink to &quot;Independent Scene Execution&quot;">​</a></h3><p>If independent execution is required, a separate setting should be made for <code>type=&quot;scene&quot;</code>. At this point, the text processing flow does not occur.</p><h3 id="blank-segment-handling" tabindex="-1">Blank Segment Handling <a class="header-anchor" href="#blank-segment-handling" aria-label="Permalink to &quot;Blank Segment Handling&quot;">​</a></h3><p>This is currently an imperfect solution; Ezlang needs to address this issue in the future.</p><p>Inconsistent code writing styles may lead to blank segments, which are skipped over directly when handling them.</p>',20)])])}const g=n(a,[["render",r]]);export{u as __pageData,g as default};
